mapper.select:
SELECT STATUS
FROM MEMBER
WHERE MEMBER_NO = #{memberNo}

SELECT COUNT(*)
FROM BUSINESS
WHERE MEMBER_NO = #{memberNo}

mapper.delete:
DELETE FROM REVIEW_REPORT
WHERE MEMBER_NO = #{memberNo}
   OR ADMIN_NO = #{memberNo}
   OR CONTENT_REVIEW_NO IN (
        SELECT REVIEW_NO FROM REVIEW WHERE MEMBER_NO = #{memberNo}
      )
   OR PRODUCT_REVIEW_NO IN (
        SELECT REVIEW_NO FROM PRODUCT_REVIEW WHERE MEMBER_NO = #{memberNo}
      )

DELETE FROM ORDER_ITEM
WHERE ORDER_NO IN (
    SELECT ORDER_NO FROM ORDERS WHERE MEMBER_NO = #{memberNo}
)

DELETE FROM CART_ITEM
WHERE CART_NO IN (
    SELECT CART_NO FROM CART WHERE MEMBER_NO = #{memberNo}
)

DELETE FROM MEMBER
WHERE MEMBER_NO = #{memberNo}
AND STATUS = 'WITHDRAWN'

mapper.update:
UPDATE EVENT
SET STATUS = #{status}
WHERE EVENT_NO = #{eventNo}

UPDATE PRODUCT
SET STATUS = #{status}
WHERE PRODUCT_NO = #{productNo}

UPDATE DELIVERY
SET STATUS = #{status},
    UPDATED_AT = SYSDATE
WHERE ORDER_ITEM_NO IN (
    SELECT ORDER_ITEM_NO FROM ORDER_ITEM WHERE ORDER_NO = #{orderNo}
)

UPDATE ORDER_ITEM
SET STATUS = 'CANCELED'
WHERE ORDER_ITEM_NO = #{orderItemNo}

UPDATE CANCEL_REQUEST
SET STATUS = #{status}
WHERE CANCEL_NO = #{cancelNo}

